1	import { Hierarchy, type ILayer, type LayerId } from "@motion-studio/shared";
2	import { isGroupLayer } from "./layer-guards";
3	import type { LayerRegistry } from "./layer-registry";
4	
5	/**
6	 * The persistent Composition Graph (GLOSSARY.md, ADR-006) — parent/child
7	 * structure of Layers, saved with the project. Built on the generic
8	 * `Hierarchy` primitive (ADR-005 #2) rather than a bespoke tree, and is the
9	 * single place allowed to mutate `ILayerBase.parentId` /
10	 * `IGroupLayer.childIds` once a layer has been added, so those two fields
11	 * can never drift out of sync with each other.
12	 */
13	export class CompositionGraph {
14	  private readonly hierarchy: Hierarchy<LayerId>;
15	
16	  constructor(private readonly registry: LayerRegistry) {
17	    this.hierarchy = new Hierarchy<LayerId>({
18	      getParentId: (id) => this.requireLayer(id).parentId,
19	      getChildIds: (id) => {
20	        const layer = this.requireLayer(id);
21	        return isGroupLayer(layer) ? layer.childIds : [];
22	      },
23	    });
24	  }
25	
26	  /**
27	   * Registers a new layer and, if it declares a `parentId`, attaches it as
28	   * that Group layer's child. Prefer this over calling `LayerRegistry.add`
29	   * directly whenever the layer has a parent, so `childIds` stays in sync.
30	   */
31	  addLayer(layer: ILayer): void {
32	    if (layer.parentId !== null) {
33	      const parent = this.requireLayer(layer.parentId);
34	      if (!isGroupLayer(parent)) {
35	        throw new Error(
36	          `CompositionGraph: layer "${layer.parentId}" is not a Group layer and cannot have children.`,
37	        );
38	      }
39	    }
40	    this.registry.add(layer);
41	    if (layer.parentId !== null) {
42	      const parent = this.requireLayer(layer.parentId);
43	      if (isGroupLayer(parent)) {
44	        parent.childIds = [...parent.childIds, layer.id];
45	      }
46	    }
47	  }
48	
49	  /**
50	   * Unregisters a layer. Fails fast if it still has children — cascade vs.
51	   * detach-children-to-root on delete is an explicit open question (see
52	   * `docs/08-layer-engine/overview.md` "Interaction with Timeline"); callers
53	   * must reparent or remove children first rather than this method silently
54	   * choosing a cascade policy.
55	   */
56	  removeLayer(id: LayerId): void {
57	    const layer = this.requireLayer(id);
58	    if (this.getChildren(id).length > 0) {
59	      throw new Error(
60	        `CompositionGraph: cannot remove "${id}" — it still has children; reparent or remove them first.`,
61	      );
62	    }
63	    if (layer.parentId !== null) {
64	      const parent = this.requireLayer(layer.parentId);
65	      if (isGroupLayer(parent)) {
66	        parent.childIds = parent.childIds.filter((childId) => childId !== id);
67	      }
68	    }
69	    this.registry.remove(id);
70	  }
71	
72	  getParent(id: LayerId): LayerId | null {
73	    return this.requireLayer(id).parentId;
74	  }
75	
76	  getChildren(id: LayerId): LayerId[] {
77	    const layer = this.requireLayer(id);
78	    return isGroupLayer(layer) ? [...layer.childIds] : [];
79	  }
80	
81	  getAncestors(id: LayerId): LayerId[] {
82	    this.requireLayer(id);
83	    return this.hierarchy.getAncestors(id);
84	  }
85	
86	  getDescendants(id: LayerId): LayerId[] {
87	    this.requireLayer(id);
88	    return this.hierarchy.getDescendants(id);
89	  }
90	
91	  /** Effective visibility = this layer and every ancestor are visible. */
92	  isEffectivelyVisible(id: LayerId): boolean {
93	    const layer = this.requireLayer(id);
94	    if (!layer.visible) {
95	      return false;
96	    }
97	    return this.getAncestors(id).every((ancestorId) => this.requireLayer(ancestorId).visible);
98	  }
99	
100	  /** Effective lock = this layer or any ancestor is locked. */
101	  isEffectivelyLocked(id: LayerId): boolean {
102	    const layer = this.requireLayer(id);
103	    if (layer.locked) {
104	      return true;
105	    }
106	    return this.getAncestors(id).some((ancestorId) => this.requireLayer(ancestorId).locked);
107	  }
108	
109	  /**
110	   * Moves `id` to be a child of `newParentId` (or a root, if null).
111	   * Validates the new parent exists and is a Group layer, and that the
112	   * move would not create a cycle, before touching any state.
113	   */
114	  reparent(id: LayerId, newParentId: LayerId | null): void {
115	    const layer = this.requireLayer(id);
116	    if (newParentId !== null) {
117	      const newParent = this.requireLayer(newParentId);
118	      if (!isGroupLayer(newParent)) {
119	        throw new Error(
120	          `CompositionGraph: layer "${newParentId}" is not a Group layer and cannot have children.`,
121	        );
122	      }
123	    }
124	    this.hierarchy.assertNoCycle(id, newParentId);
125	
126	    const oldParentId = layer.parentId;
127	    if (oldParentId !== null) {
128	      const oldParent = this.requireLayer(oldParentId);
129	      if (isGroupLayer(oldParent)) {
130	        oldParent.childIds = oldParent.childIds.filter((childId) => childId !== id);
131	      }
132	    }
133	
134	    layer.parentId = newParentId;
135	
136	    if (newParentId !== null) {
137	      const newParent = this.requireLayer(newParentId);
138	      if (isGroupLayer(newParent)) {
139	        newParent.childIds = [...newParent.childIds, id];
140	      }
141	    }
142	  }
143	
144	  private requireLayer(id: LayerId): ILayer {
145	    const layer = this.registry.get(id);
146	    if (!layer) {
147	      throw new Error(`CompositionGraph: unknown layer: "${id}"`);
148	    }
149	    return layer;
150	  }
151	}
152

