14	
15	/**
16	 * Owns the "when" (CLAUDE.md engine ownership table): Composition → Track →
17	 * TrackItem, referencing Layers by id only. Never touches rendering,
18	 * decoding, or storage — see ARCHITECTURE.md §3. Composes the three
19	 * registries and is the only thing allowed to mutate `IComposition.tracks`
20	 * or `ITrack.items` after creation, so those arrays can never drift out of
21	 * sync with the registries.
22	 */
23	export class TimelineEngine implements IEngine {
24	  readonly name = "Timeline";
25	  readonly compositions = new CompositionRegistry();
26	  readonly tracks = new TrackRegistry();
27	  readonly trackItems = new TrackItemRegistry();
28	
29	  initialize(): void {
30	    // No async setup required — registries are ready on construction.
31	  }
32	
33	  ready(): void {}
34	
35	  dispose(): void {
36	    this.compositions.clear();
37	    this.tracks.clear();
38	    this.trackItems.clear();
39	  }
40	
41	  addTrack(compositionId: CompositionId, track: ITrack): void {
42	    const composition = this.requireComposition(compositionId);
43	    this.tracks.add(track);
44	    composition.tracks = [...composition.tracks, track.id];
45	  }
46	
47	  /** Fails fast if the track still has items — callers must remove/move them first, mirroring `CompositionGraph.removeLayer`. */
48	  removeTrack(compositionId: CompositionId, trackId: TrackId): void {
49	    const composition = this.requireComposition(compositionId);
50	    const track = this.requireTrack(trackId);
51	    if (track.items.length > 0) {
52	      throw new Error(
53	        `TimelineEngine: cannot remove track "${trackId}" — it still has items; remove them first.`,
54	      );
55	    }
56	    composition.tracks = composition.tracks.filter((id) => id !== trackId);
57	    this.tracks.remove(trackId);
58	  }
59	
60	  addTrackItem(item: ITrackItem): void {
61	    const track = this.requireTrack(item.trackId);
62	    if (this.overlaps(item.trackId, item.id, item.startTick, item.durationTicks)) {
63	      throw new Error(
64	        `TimelineEngine: track item "${item.id}" overlaps an existing item on track "${item.trackId}".`,
65	      );
66	    }
67	    this.trackItems.add(item);
68	    track.items = [...track.items, item.id];
69	  }
70	
71	  removeTrackItem(id: TrackItemId): void {
72	    const item = this.requireTrackItem(id);
73	    const track = this.requireTrack(item.trackId);
74	    track.items = track.items.filter((itemId) => itemId !== id);
75	    this.trackItems.remove(id);
76	  }
77	
78	  /** Moves an item to a new track and/or start tick, validating there's no overlap at the destination first. */
79	  moveTrackItem(id: TrackItemId, toTrackId: TrackId, toStartTick: Tick): void {
80	    const item = this.requireTrackItem(id);
81	    const toTrack = this.requireTrack(toTrackId);
82	    if (this.overlaps(toTrackId, id, toStartTick, item.durationTicks)) {
83	      throw new Error(
84	        `TimelineEngine: moving track item "${id}" to track "${toTrackId}" at tick ${toStartTick} would overlap an existing item.`,
85	      );
86	    }
87	    const fromTrack = this.requireTrack(item.trackId);
88	    if (fromTrack.id !== toTrack.id) {
89	      fromTrack.items = fromTrack.items.filter((itemId) => itemId !== id);
90	      toTrack.items = [...toTrack.items, id];
91	    }
92	    item.trackId = toTrackId;
93	    item.startTick = toStartTick;
94	  }
95	
96	  /**
97	   * Trims an item's `in` or `out` edge to a new absolute position on the
98	   * Timeline, adjusting `startTick`/`durationTicks` and the corresponding
99	   * `trimInTick`/`trimOutTick` offset into the source media together so
100	   * they never drift apart. See docs/07-timeline-engine/trimming.md.
101	   */
102	  trimTrackItem(id: TrackItemId, edge: "in" | "out", newTimelineTick: Tick): void {
103	    const item = this.requireTrackItem(id);
104	    let nextStartTick = item.startTick;
105	    let nextDurationTicks = item.durationTicks;
106	    let nextTrimInTick = item.trimInTick;
107	    let nextTrimOutTick = item.trimOutTick;
108	
109	    if (edge === "in") {
110	      const deltaTicks = newTimelineTick - item.startTick;
111	      nextStartTick = newTimelineTick;
112	      nextDurationTicks = (item.durationTicks - deltaTicks) as Tick;
113	      nextTrimInTick = (item.trimInTick + deltaTicks) as Tick;
114	    } else {
115	      const itemEnd = item.startTick + item.durationTicks;
116	      const deltaTicks = newTimelineTick - itemEnd;
117	      nextDurationTicks = (item.durationTicks + deltaTicks) as Tick;
118	      nextTrimOutTick = (item.trimOutTick + deltaTicks) as Tick;
119	    }
120	
121	    if (nextDurationTicks <= 0) {
122	      throw new Error(`TimelineEngine: trimming "${id}" would leave a non-positive duration.`);
123	    }
124	    if (nextTrimInTick < 0 || nextTrimInTick >= nextTrimOutTick) {
125	      throw new Error(`TimelineEngine: trimming "${id}" would produce an invalid trim range.`);
126	    }
127	    if (this.overlaps(item.trackId, id, nextStartTick, nextDurationTicks)) {
128	      throw new Error(`TimelineEngine: trimming "${id}" would overlap an existing item.`);
129	    }
130	
131	    item.startTick = nextStartTick;
132	    item.durationTicks = nextDurationTicks;
133	    item.trimInTick = nextTrimInTick;
134	    item.trimOutTick = nextTrimOutTick;
135	  }
136	
137	  /**
138	   * Repositions an item's start tick on its current track without an
139	   * overlap check. Only safe for callers (e.g. `RippleDeleteCommand`) that
140	   * can prove the shift preserves non-overlap by construction — everything
141	   * else should go through `moveTrackItem`.
142	   */
143	  shiftTrackItemStart(id: TrackItemId, toStartTick: Tick): void {
144	    const item = this.requireTrackItem(id);
145	    item.startTick = toStartTick;
146	  }
147	
148	  getTrackItemsSorted(trackId: TrackId): ITrackItem[] {
149	    const track = this.requireTrack(trackId);
150	    return track.items
151	      .map((itemId) => this.requireTrackItem(itemId))
152	      .sort((a, b) => a.startTick - b.startTick);
153	  }
154	
155	  overlaps(
156	    trackId: TrackId,
157	    excludeItemId: TrackItemId | null,
158	    startTick: Tick,
159	    durationTicks: Tick,
160	  ): boolean {
161	    const end = startTick + durationTicks;
162	    return this.getTrackItemsSorted(trackId).some((existing) => {
163	      if (existing.id === excludeItemId) {
164	        return false;
165	      }
166	      const existingEnd = existing.startTick + existing.durationTicks;
167	      return startTick < existingEnd && existing.startTick < end;
168	    });
169	  }
170	
171	  requireComposition(id: CompositionId): IComposition {
172	    const composition = this.compositions.get(id);
173	    if (!composition) {
174	      throw new Error(`TimelineEngine: unknown composition: "${id}"`);
175	    }
176	    return composition;
177	  }
178	
179	  requireTrack(id: TrackId): ITrack {
180	    const track = this.tracks.get(id);
181	    if (!track) {
182	      throw new Error(`TimelineEngine: unknown track: "${id}"`);
183	    }
184	    return track;
185	  }
186	
187	  requireTrackItem(id: TrackItemId): ITrackItem {
188	    const item = this.trackItems.get(id);
189	    if (!item) {
190	      throw new Error(`TimelineEngine: unknown track item: "${id}"`);
191	    }
192	    return item;
193	  }
194	}
