1	import type {
2	  AnimationClipId,
3	  IAnimationClip,
4	  IEngine,
5	  IKeyframe,
6	  IPropertyTrack,
7	  LayerId,
8	  PropertyTrackId,
9	  Tick,
10	} from "@motion-studio/shared";
11	import { AnimationClipRegistry } from "./animation-clip-registry";
12	import { registerBuiltinProperties } from "./builtin-properties";
13	import { evaluateSegment, SegmentLocator } from "./evaluator";
14	import { AnimatablePropertyRegistry } from "./property-registry";
15	import { PropertyTrackRegistry } from "./property-track-registry";
16	
17	/**
18	 * Owns "per-property keyframes/interpolation, evaluated per frame"
19	 * (CLAUDE.md engine ownership table). Never touches rendering or storage.
20	 * Composes the property/clip/track registries and is the only thing
21	 * allowed to mutate an `IAnimationClip.propertyTrackIds` array or an
22	 * `IPropertyTrack.keyframes` array after creation — mirrors
23	 * `TimelineEngine`'s ownership of `ITrack.items`.
24	 */
25	export class AnimationEngine implements IEngine {
26	  readonly name = "Animation";
27	  readonly properties = new AnimatablePropertyRegistry();
28	  readonly clips = new AnimationClipRegistry();
29	  readonly propertyTracks = new PropertyTrackRegistry();
30	
31	  private readonly segmentLocators = new Map<PropertyTrackId, SegmentLocator>();
32	
33	  initialize(): void {
34	    registerBuiltinProperties(this.properties);
35	  }
36	
37	  ready(): void {}
38	
39	  dispose(): void {
40	    this.properties.clear();
41	    this.clips.clear();
42	    this.propertyTracks.clear();
43	    this.segmentLocators.clear();
44	  }
45	
46	  /** Throws if the Layer already has a Clip — see `IAnimationClip` doc comment on multi-clip blending (ADR-005 #3, open). */
47	  addClip(clip: IAnimationClip): void {
48	    if (this.getClipForLayer(clip.layerId)) {
49	      throw new Error(
50	        `AnimationEngine: layer "${clip.layerId}" already has an AnimationClip — multi-clip blending is not yet supported (ADR-005 #3 is still open).`,
51	      );
52	    }
53	    this.clips.add(clip);
54	  }
55	
56	  removeClip(id: AnimationClipId): void {
57	    const clip = this.requireClip(id);
58	    for (const trackId of clip.propertyTrackIds) {
59	      this.propertyTracks.remove(trackId);
60	      this.segmentLocators.delete(trackId);
61	    }
62	    this.clips.remove(id);
63	  }
64	
65	  getClipForLayer(layerId: LayerId): IAnimationClip | undefined {
66	    return this.clips.getAll().find((clip) => clip.layerId === layerId);
67	  }
68	
69	  /** Adds a Property Track to its Clip, rejecting a second track for a property the Clip already animates. */
70	  addPropertyTrack(track: IPropertyTrack): void {
71	    const clip = this.requireClip(track.clipId);
72	    const definition = this.properties.require(clip.layerType, track.propertyKey);
73	    if (definition.valueType !== track.valueType) {
74	      throw new Error(
75	        `AnimationEngine: property "${track.propertyKey}" on layer type "${clip.layerType}" is registered as ` +
76	          `"${definition.valueType}", not "${track.valueType}"`,
77	      );
78	    }
79	    const duplicate = clip.propertyTrackIds
80	      .map((id) => this.propertyTracks.get(id))
81	      .find((existing) => existing?.propertyKey === track.propertyKey);
82	    if (duplicate) {
83	      throw new Error(
