1	/** Axis-aligned bounds in a node's local coordinate space (e.g. layer bounds, clip layout rect). */
2	export interface IBounds {
3	  x: number;
4	  y: number;
5	  width: number;
6	  height: number;
7	}
8	
9	/** Read-only view a domain object exposes so `DirtyTrackedGraph` can walk it. */
10	export interface IDirtyGraphNodeAccessor<TId> {
11	  getParentId(id: TId): TId | null;
12	  getChildIds(id: TId): readonly TId[];
13	  getBounds(id: TId): IBounds;
14	  isVisible(id: TId): boolean;
15	}
16	
17	function intersects(a: IBounds, b: IBounds): boolean {
18	  return a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y;
19	}
20	
21	/**
22	 * Generic, storage-free dirty-tracked/virtualization-ready node graph
23	 * (ADR-005 primitive #1 — see docs/DECISIONS.md). Owns only the dirty-flag
24	 * set; structure (parent/child, bounds, visibility) is read through the
25	 * accessor a caller provides. Backs the Rendering Engine's ephemeral
26	 * per-frame Scene Graph (`05-rendering-engine/scene-graph.md`) today;
27	 * Timeline UI's virtualized clip layout and Canvas overlay nodes are
28	 * documented future consumers of the same primitive.
29	 */
30	export class DirtyTrackedGraph<TId> {
31	  private readonly dirty = new Set<TId>();
32	
