25	
26	/**
27	 * Stores large binaries (media files, AI models, voice cache, exports) —
28	 * see docs/12-storage/opfs.md. A VFS path maps to nested OPFS directories,
29	 * with the final segment as the file name.
30	 */
31	export class OpfsAdapter implements IStorageAdapter {
32	  private readonly getRoot: OpfsRootFactory;
33	  private rootPromise: Promise<IOpfsDirectoryHandle> | null = null;
34	
35	  constructor(dependencies: IOpfsAdapterDependencies = {}) {
36	    this.getRoot = dependencies.getRoot ?? defaultOpfsRootFactory;
37	  }
38	
39	  async read(path: string): Promise<Uint8Array | undefined> {
40	    const file = await this.locateFile(path);
41	    if (!file) {
42	      return undefined;
43	    }
44	    const blob = await file.getFile();
45	    return new Uint8Array(await blob.arrayBuffer());
46	  }
47	
48	  async write(path: string, data: Uint8Array): Promise<void> {
49	    const { dirs, name } = splitPath(path);
50	    const dir = await this.ensureDir(dirs, true);
51	    if (!dir) {
52	      throw new Error(`Failed to create OPFS directory for path "${path}".`);
53	    }
54	    const file = await dir.getFileHandle(name, { create: true });
55	    const writable = await file.createWritable();
56	    await writable.write(data);
57	    await writable.close();
58	  }
59	
60	  async delete(path: string): Promise<void> {
61	    const { dirs, name } = splitPath(path);
62	    const dir = await this.ensureDir(dirs, false);
63	    if (!dir) {
64	      return;
65	    }
66	    try {
67	      await dir.removeEntry(name, { recursive: true });
68	    } catch (error) {
69	      if (!isNotFoundError(error)) {
70	        throw error;
71	      }
72	    }
73	  }
74	
75	  async exists(path: string): Promise<boolean> {
76	    return (await this.locateFile(path)) !== undefined;
77	  }
78	
79	  async list(prefix: string): Promise<string[]> {
80	    const out: string[] = [];
81	    // Every real caller passes a directory prefix ending in "/" (see
82	    // json-repository.ts, project-repository.ts, thumbnail-cache.ts) — for
83	    // that shape we can descend straight to the matching directory instead
84	    // of walking the entire OPFS tree and filtering afterwards.
85	    if (prefix.endsWith("/")) {
86	      const dirPath = prefix.slice(0, -1);
87	      const dir = await this.ensureDir(dirPath.split("/").filter(Boolean), false);
88	      if (dir) {
89	        await this.walk(dir, dirPath, out);
90	      }
91	      return out;
92	    }
93	    const root = await this.ensureRoot();
94	    await this.walk(root, "", out);
95	    return out.filter((path) => path.startsWith(prefix));
96	  }
97	
98	  private async walk(dir: IOpfsDirectoryHandle, currentPath: string, out: string[]): Promise<void> {
99	    for await (const [name, handle] of dir.entries()) {
100	      const path = currentPath ? `${currentPath}/${name}` : name;
101	      if (handle.kind === "file") {
102	        out.push(path);
103	      } else {
104	        await this.walk(handle, path, out);
105	      }
106	    }
107	  }
108	
109	  private async locateFile(path: string): Promise<IOpfsFileHandle | undefined> {
110	    const { dirs, name } = splitPath(path);
111	    const dir = await this.ensureDir(dirs, false);
112	    if (!dir) {
113	      return undefined;
114	    }
115	    try {
116	      return await dir.getFileHandle(name, { create: false });
117	    } catch (error) {
118	      if (isNotFoundError(error)) {
119	        return undefined;
120	      }
121	      throw error;
122	    }
123	  }
124	
125	  private async ensureDir(
126	    segments: string[],
127	    create: boolean,
128	  ): Promise<IOpfsDirectoryHandle | undefined> {
129	    let dir = await this.ensureRoot();
130	    for (const segment of segments) {
131	      try {
132	        dir = await dir.getDirectoryHandle(segment, { create });
133	      } catch (error) {
134	        if (isNotFoundError(error)) {
135	          return undefined;
136	        }
137	        throw error;
138	      }
139	    }
140	    return dir;
141	  }
142	
143	  private ensureRoot(): Promise<IOpfsDirectoryHandle> {
144	    if (!this.rootPromise) {
145	      this.rootPromise = this.getRoot();
146	    }
147	    return this.rootPromise;
148	  }
149	}
