6	export type PluginPermission = (typeof PLUGIN_PERMISSIONS)[number];
7	
8	export function isKnownPluginPermission(value: string): value is PluginPermission {
9	  return (PLUGIN_PERMISSIONS as readonly string[]).includes(value);
10	}
11	
12	/**
13	 * Declares a plugin's identity plus the sub-APIs it needs — the
14	 * "RequestingPermissions" step of `PluginLifecycleState`
15	 * (`docs/16-plugin-system/lifecycle.md`). `id`/`name`/`version` are
16	 * declared separately from the `IPlugin` instance so `PluginRegistry.register()`
17	 * can catch a mismatched manifest (e.g. a manifest built for the wrong
18	 * plugin) before ever calling into plugin code.
19	 */
20	export interface IPluginManifest {
21	  readonly id: string;
22	  readonly name: string;
23	  readonly version: string;
24	  readonly permissions: readonly PluginPermission[];
25	}
26	
27	/**
28	 * Sandbox enforcement (PLAN.md "Plugin sandbox: plugins only see public
29	 * APIs, never engine internals"): a plugin receives only the sub-APIs it
