3	import { useEffect } from "react";
4	import { PlaybackState } from "@motion-studio/shared";
5	import { useEditorKernel } from "./editor-kernel-provider";
6	import { ToolbarPanel } from "./toolbar/toolbar-panel";
7	import { CanvasPanel } from "./canvas/canvas-panel";
8	import { TimelinePanel } from "./timeline/timeline-panel";
9	import { InspectorPanel } from "./inspector/inspector-panel";
10	import { AssetBrowserPanel } from "./asset-browser/asset-browser-panel";
11	import { useTimelineStore } from "../state/use-timeline-store";
12	import { useCanvasStore } from "../state/use-canvas-store";
13	import type { EditorKernel } from "../editor-kernel/editor-kernel";
14	
15	const GLOBAL_BINDINGS = [
16	  { key: "Delete", commandId: "DeleteSelection" },
17	  { key: "Backspace", commandId: "DeleteSelection" },
18	  { key: "Mod+Z", commandId: "Undo" },
19	  { key: "Mod+Shift+Z", commandId: "Redo" },
20	  { key: " ", commandId: "TogglePlayback" },
21	  { key: "V", commandId: "ActivateSelectTool" },
22	] as const;
23	
24	function dispatchShortcutCommand(kernel: EditorKernel, commandId: string): void {
25	  switch (commandId) {
26	    case "DeleteSelection": {
27	      const { selection, clearSelection } = useTimelineStore.getState();
28	      kernel.timelineEditor.deleteSelection({
29	        type: "DeleteSelection",
30	        payload: { trackItemIds: selection.trackItemIds },
31	      });
32	      clearSelection();
33	      return;
34	    }
35	    case "Undo":
36	      if (kernel.commandBus.canUndo) {
37	        kernel.commandBus.undo();
38	      }
39	      return;
40	    case "Redo":
41	      if (kernel.commandBus.canRedo) {
42	        kernel.commandBus.redo();
43	      }
44	      return;
45	    case "TogglePlayback":
46	      if (kernel.playback.playbackState === PlaybackState.Playing) {
47	        kernel.playback.pause();
48	      } else {
49	        kernel.playback.play();
50	      }
51	      return;
52	    case "ActivateSelectTool":
53	      kernel.toolRegistry.activate("select");
54	      useCanvasStore.getState().setActiveTool("select");
55	      return;
56	    default:
57	      return;
58	  }
59	}
60	
61	function isEditableTarget(target: EventTarget | null): boolean {
62	  if (!(target instanceof HTMLElement)) {
63	    return false;
64	  }
65	  return target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable;
66	}
67	
68	/**
69	 * Fixed CSS grid — Toolbar, Timeline, Inspector, Asset Browser, Canvas each
70	 * in a static cell. No dockable Split/Stack/Panel tree, no floating panels,
71	 * no layout-undo (ADR-011) — `docs/17-ui/docking.md`'s real engine is
72	 * deferred to its own future pass (Phase 15 scope decision).
73	 */
74	export function EditorShell(): JSX.Element {
75	  const kernel = useEditorKernel();
76	
77	  useEffect(() => {
78	    for (const binding of GLOBAL_BINDINGS) {
79	      kernel.shortcuts.register({ key: binding.key, commandId: binding.commandId, scope: "Global" });
80	    }
81	
82	    const handleKeyDown = (event: KeyboardEvent): void => {
83	      if (isEditableTarget(event.target)) {
84	        return;
85	      }
86	      const commandId = kernel.shortcuts.resolve(event);
87	      if (!commandId) {
88	        return;
89	      }
90	      event.preventDefault();
91	      dispatchShortcutCommand(kernel, commandId);
92	    };
93	
94	    window.addEventListener("keydown", handleKeyDown);
95	    return () => {
96	      window.removeEventListener("keydown", handleKeyDown);
97	      for (const binding of GLOBAL_BINDINGS) {
98	        kernel.shortcuts.unregister(binding.key, "Global");
99	      }
100	    };
101	  }, [kernel]);
102	
103	  return (
104	    <div className="grid h-screen grid-rows-[auto_1fr_260px] bg-editor-bg text-editor-text">
105	      <ToolbarPanel />
106	      <div className="grid grid-cols-[240px_1fr_280px] overflow-hidden">
107	        <AssetBrowserPanel />
108	        <CanvasPanel />
109	        <InspectorPanel />
110	      </div>
111	      <TimelinePanel />
112	    </div>
113	  );
114	}
