      readonly assetType: AssetType;
      readonly name: string;
      readonly startTick: Tick;
      readonly durationTicks: Tick;
    }
  > {}

export interface IMoveTrackItemIntent
  extends IIntent<
    "MoveTrackItem",
    { readonly trackItemId: TrackItemId; readonly toTrackId: TrackId; readonly toStartTick: Tick }
  > {}

export interface IDeleteSelectionIntent
  extends IIntent<"DeleteSelection", { readonly trackItemIds: readonly TrackItemId[] }> {}

export interface ISetLayerPropertyIntent
  extends IIntent<
    "SetLayerProperty",
    { readonly layerId: LayerId; readonly propertyKey: string; readonly value: unknown }
  > {}

export interface IAddKeyframeIntent
  extends IIntent<
    "AddKeyframe",
    {
      readonly layerId: LayerId;
      readonly layerType: LayerType;
      readonly propertyKey: string;
      readonly tick: Tick;
      readonly value: unknown;
    }
  > {}

