import { chromium } from "playwright";

const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1400, height: 900 } });
const page = await context.newPage();
const errors = [];
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(msg.text());
});
page.on("pageerror", (err) => errors.push(String(err)));

await page.goto("http://localhost:3002");
await page.waitForSelector("text=Motion Studio", { timeout: 15000 });
await page.screenshot({ path: "/tmp/studio-1-loaded.png" });

// Import an asset: create a tiny fake PNG file and import via the file input.
const pngBase64 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";
const buffer = Buffer.from(pngBase64, "base64");

const fileInput = page.locator('input[type="file"]');
await fileInput.setInputFiles({ name: "test.png", mimeType: "image/png", buffer });
await page.waitForTimeout(1000);
await page.screenshot({ path: "/tmp/studio-2-imported.png" });

const assetTile = page.locator("text=test.png");
await assetTile.waitFor({ timeout: 5000 });
console.log("Asset tile visible:", await assetTile.isVisible());

// Drag the asset tile onto the video track lane.
const trackLane = page.locator(".relative.h-16").first();
const assetBox = await assetTile.boundingBox();
const trackBox = await trackLane.boundingBox();
if (assetBox && trackBox) {
  await page.mouse.move(assetBox.x + assetBox.width / 2, assetBox.y + assetBox.height / 2);
  await page.mouse.down();
  await page.mouse.move(trackBox.x + 50, trackBox.y + trackBox.height / 2, { steps: 10 });
  await page.mouse.move(trackBox.x + 60, trackBox.y + trackBox.height / 2, { steps: 5 });
  await page.mouse.up();
}
await page.waitForTimeout(500);
await page.screenshot({ path: "/tmp/studio-3-dropped.png" });

console.log("Console/page errors:", errors);

await browser.close();

