// Sample a pixel in the top-left region via a 2D snapshot trick: draw the canvas onto an offscreen 2D canvas.
const pixel = await page.locator("canvas").first().evaluate((c) => {
  const off = document.createElement("canvas");
  off.width = c.width;
  off.height = c.height;
  const ctx = off.getContext("2d");
  ctx.drawImage(c, 0, 0);
  const data = ctx.getImageData(50, 50, 1, 1).data;
  return Array.from(data);
});
console.log("pixel at (50,50):", pixel);

await browser.close();
